import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Loader2, Play } from 'lucide-react'
import { api, errorMessage } from '@/lib/api'
import { Alert, Button, Modal, Skeleton, StatusBadge } from '@/components/ui'
import { useToast } from '@/components/feedback'

// Synthetic applicants generated by the ML service's data_gen. Each one runs the real pipeline.

/** The sample list (loaded once, when `enabled`) and a `start(key)` that creates the application and opens it. */
function useSamples(enabled = true) {
  const [samples, setSamples] = useState(null)
  const [error, setError] = useState('')
  const [starting, setStarting] = useState('')
  const navigate = useNavigate()
  const toast = useToast()

  useEffect(() => {
    if (!enabled || samples) return
    api.get('/samples').then(r => setSamples(r.data)).catch(err => setError(errorMessage(err)))
  }, [enabled, samples])

  const start = async key => {
    setStarting(key)
    try {
      const { data } = await api.post(`/samples/${key}`)
      toast('Sample applicant created. Reading the documents now.')
      navigate(`/applications/${data.id}`)
    } catch (err) {
      toast(errorMessage(err), 'error')
      setStarting('')
    }
  }
  return { samples, error, starting, start }
}

// The issues that demo best, in order; any other issue comes after them.
const FEATURED_ISSUES = [null, 'balance_edited', 'net_pay_edited', 'salary_mismatch', 'fake_credit']
const rank = issue => (FEATURED_ISSUES.includes(issue) ? FEATURED_ISSUES.indexOf(issue) : FEATURED_ISSUES.length)

/** One clean applicant, then one per planted issue: the demo's best story in four cards. */
function featured(samples, n = 4) {
  const seen = new Set()
  const picks = samples.filter(s => (seen.has(s.issue) ? false : seen.add(s.issue)))
  return picks.sort((a, b) => rank(a.issue) - rank(b.issue)).slice(0, n)
}

const fileSummary = files => {
  const payslips = files.filter(f => f.startsWith('payslip')).length
  const photos = files.filter(f => /\.(jpe?g|png|webp)$/i.test(f)).length
  const parts = [payslips && `${payslips} payslips`, files.some(f => f.startsWith('bank')) && 'bank statement', files.some(f => f.startsWith('form16')) && 'Form 16'].filter(Boolean)
  return `${parts.join(', ')}${photos ? `. ${photos === 1 ? 'One is a phone photo' : `${photos} are phone photos`}.` : ''}`
}

function SampleCard({ s, starting, onStart }) {
  const busy = starting === s.key
  return (
    <button
      type="button"
      disabled={!!starting}
      onClick={() => onStart(s.key)}
      className="group flex flex-col rounded-lg border border-line bg-surface p-5 text-left transition hover:border-ink/30 focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 disabled:cursor-wait disabled:opacity-60"
    >
      <div className="text-xs font-medium text-ink-3">{s.issue ? 'Planted issue' : 'Nothing planted'}</div>
      <div className="mt-1 text-[15px] font-medium leading-snug text-ink">{s.issue ? s.label : 'A clean, honest file'}</div>
      <div className="mt-4 font-serif text-lg text-ink">{s.applicant_name}</div>
      <div className="text-xs text-ink-3">{s.declared_employer}</div>
      <p className="mb-5 mt-2 text-xs leading-relaxed text-ink-3">{fileSummary(s.files)}</p>
      <div className="mt-auto flex items-center justify-between gap-2 border-t border-line pt-3.5">
        <span className="flex items-center gap-2 text-xs text-ink-3">Should be <StatusBadge status={s.expected} size="sm" /></span>
        <span className="inline-flex items-center gap-1.5 text-sm font-medium text-ink group-hover:text-brand-600">
          {busy ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Play className="h-3.5 w-3.5" />}Run
        </span>
      </div>
    </button>
  )
}

/** The home screen's sample cards, with the full list in a modal. */
export function SampleStrip() {
  const { samples, error, starting, start } = useSamples()
  const [all, setAll] = useState(false)
  if (error || samples?.length === 0) return null
  return (
    <section id="samples" className="scroll-mt-24">
      <SamplePicker open={all} onClose={() => setAll(false)} />
      <div className="mb-5 flex flex-wrap items-end justify-between gap-3">
        <div>
          <h2 className="font-serif text-[1.7rem] text-ink">Try a sample applicant</h2>
          <p className="mt-1 max-w-2xl text-sm text-ink-2">Synthetic documents that run through the real pipeline. Some have something planted in them. Run one and see whether it gets caught.</p>
        </div>
        {samples?.length > 4 && <button type="button" onClick={() => setAll(true)} className="text-sm font-medium text-brand-600 underline-offset-2 hover:underline">See all {samples.length}</button>}
      </div>
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {!samples && [0, 1, 2, 3].map(i => <Skeleton key={i} className="h-60" />)}
        {samples && featured(samples).map(s => <SampleCard key={s.key} s={s} starting={starting} onStart={start} />)}
      </div>
    </section>
  )
}

export default function SamplePicker({ open, onClose }) {
  const { samples, error, starting, start } = useSamples(open)

  return (
    <Modal open={open} onClose={onClose} width="max-w-2xl" title="Sample applicants" subtitle="Synthetic payslips, a bank statement and Form 16. Some have a planted issue the checks should catch.">
      {error && <Alert>{error}</Alert>}
      {!samples && !error && <div className="space-y-2"><Skeleton className="h-14" /><Skeleton className="h-14" /><Skeleton className="h-14" /></div>}
      {samples?.length === 0 && (
        <Alert kind="info" title="No samples generated yet">
          Run <code className="font-mono">python -m data_gen.generate --split dev --count 10 --seed 1</code> in income-verify-ml.
        </Alert>
      )}
      {samples?.length > 0 && (
        <ul className="divide-y divide-line">
          {samples.map(s => (
            <li key={s.key} className="flex flex-wrap items-center gap-3 py-3 sm:flex-nowrap">
              <div className="min-w-0 flex-1">
                <div className="truncate text-sm font-medium text-ink">{s.issue ? s.label : 'Nothing planted'}</div>
                <div className="truncate text-xs text-ink-3">{s.applicant_name}, {s.declared_employer}</div>
              </div>
              <StatusBadge status={s.expected} size="sm" />
              <Button size="sm" variant="secondary" icon={Play} busy={starting === s.key} disabled={!!starting} onClick={() => start(s.key)}>Run</Button>
            </li>
          ))}
        </ul>
      )}
    </Modal>
  )
}
